import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"缓存","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/advanced/caching.md","filePath":"zh-CN/advanced/caching.md","lastUpdated":1784903584000}'),c={name:"zh-CN/advanced/caching.md"};function i(d,a,o,l,p,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>swag2mcp 会缓存下载的规范文件，以便 MCP 服务器在后续启动时更快。它不会每次都下载相同的规范文件，而是重用缓存的副本。</p><h2 id="缓存工作原理" tabindex="-1">缓存工作原理 <a class="header-anchor" href="#缓存工作原理" aria-label="Permalink to &quot;缓存工作原理&quot;">​</a></h2><p>当你添加带有远程 URL 的 spec 时，swag2mcp 会下载它并保存到 <code>cache/</code> 目录。下次启动时，它会检查缓存的副本是否仍然有效。如果是，则跳过下载。</p><h3 id="哪些内容会被缓存" tabindex="-1">哪些内容会被缓存 <a class="header-anchor" href="#哪些内容会被缓存" aria-label="Permalink to &quot;哪些内容会被缓存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>行为</th></tr></thead><tbody><tr><td><strong>远程 URL</strong>（http/https）</td><td>始终缓存。下载一次，重用直到缓存过期。</td></tr><tr><td><strong><code>specs/</code> 中的本地文件</strong></td><td>直接从 <code>specs/</code> 目录使用。从不缓存 — 更改立即可见。</td></tr><tr><td><strong><code>specs/</code> 外部的本地文件</strong></td><td>复制到缓存。如果源文件更改（修改时间），缓存失效。</td></tr></tbody></table><h3 id="缓存过期-ttl" tabindex="-1">缓存过期（TTL） <a class="header-anchor" href="#缓存过期-ttl" aria-label="Permalink to &quot;缓存过期（TTL）&quot;">​</a></h3><p>每个缓存文件获得 <strong>1 小时到 48 小时</strong> 之间的随机过期时间。随机性防止所有缓存文件同时过期（这会导致下载风暴）。</p><ul><li>TTL 在每次 MCP 服务器启动时重置</li><li>如果缓存文件仍在 TTL 内，则重用</li><li>如果 TTL 已过期，则重新下载文件</li></ul><h3 id="缓存结构" tabindex="-1">缓存结构 <a class="header-anchor" href="#缓存结构" aria-label="Permalink to &quot;缓存结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # 缓存的规范文件</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # 元数据（来源、TTL、缓存时间）</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>缓存键源自规范文件 URL 或路径。每个缓存文件都有一个配套的 <code>.meta</code> 文件，存储缓存时间和过期时间。</p><h2 id="管理缓存" tabindex="-1">管理缓存 <a class="header-anchor" href="#管理缓存" aria-label="Permalink to &quot;管理缓存&quot;">​</a></h2><h3 id="强制刷新" tabindex="-1">强制刷新 <a class="header-anchor" href="#强制刷新" aria-label="Permalink to &quot;强制刷新&quot;">​</a></h3><p>运行 <code>swag2mcp update</code> 清除整个缓存并重新下载所有规范文件：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>这会验证配置、清除缓存并重新下载所有内容。</p><h3 id="手动清除缓存" tabindex="-1">手动清除缓存 <a class="header-anchor" href="#手动清除缓存" aria-label="Permalink to &quot;手动清除缓存&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>这会删除所有缓存的规范文件和保存的 API 响应。下次启动 MCP 服务器时，所有规范将重新下载。</p><h3 id="自动清理" tabindex="-1">自动清理 <a class="header-anchor" href="#自动清理" aria-label="Permalink to &quot;自动清理&quot;">​</a></h3><p>当 MCP 服务器启动（<code>swag2mcp mcp</code>）时，超过 48 小时的保存的 API 响应会自动删除。这防止 <code>responses/</code> 目录无限增长。</p><h2 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to &quot;重要说明&quot;">​</a></h2><ul><li><strong><code>specs/</code> 中的本地文件从不缓存</strong> — 如果你直接在 <code>specs/</code> 目录中编辑规范文件，更改立即可见，无需清除缓存</li><li><strong>远程 URL 始终缓存</strong> — 除了运行 <code>swag2mcp update</code> 或 <code>swag2mcp clean</code> 之外，无法绕过远程 URL 的缓存</li><li><strong>缓存是本地的</strong> — 存储在磁盘上，不会在机器之间同步。使用 <code>swag2mcp export</code> 和 <code>swag2mcp import</code> 在机器之间传输规范</li></ul>`,25)])])}const g=e(c,[["render",i]]);export{b as __pageData,g as default};
